action_details.action_postfix:
// Economic nexus established per Wayfair - filing required
// MA threshold: $500,000 in gross receipts
// Apportionment will be calculated by tables 7000-7500

// No nexus - no filing required
apportionment.state_tax 0.0 xdef
apportionment.state_refund_or_owed apportionment.state_payments xdef

// Calculate state additions (MA-specific)
0.0 /additions xdef

// MA requires addback of federal interest (U.S. obligations)
// additions revenue.federal_bond_interest add /additions xdef

// MA requires addback of IRC 199A deduction (MA doesn't conform)
// additions result.section_199a_deduction add /additions xdef

// MA requires addback of certain depreciation differences
// additions result.federal_ma_depreciation_difference add /additions xdef

apportionment.state_additions additions xdef

// Calculate state subtractions (MA-specific)
0.0 /subtractions xdef

// MA allows deduction for dividends from 15%+ owned subsidiaries
// subtractions revenue.qualified_dividend_deduction add /subtractions xdef

// MA allows deduction for certain capital gains on qualified investments
// subtractions result.ma_qualified_capital_gain add /subtractions xdef

// MA NOL deduction (limited to certain years)
// subtractions result.ma_nol_deduction add /subtractions xdef

apportionment.state_subtractions subtractions xdef

// MA uses 8% flat rate on apportioned net income
apportionment.state_taxable_income apportionment.state_tax_rate mul
/state_tax_before_credits xdef

// Subtract state credits (EDIP, R&D, film credits, etc.)
state_tax_before_credits apportionment.state_credits sub
0.0 max
/apportionment.state_tax xdef

// Calculate refund or amount owed
apportionment.state_payments apportionment.state_tax sub
/apportionment.state_refund_or_owed xdef
